mapper.select:
SELECT R.REPORT_NUM as reportNum, R.REPORTER_NUM as reporterNum, U.USER_NICKNAME as reporterNickname, R.TARGET_TYPE as targetType, R.TARGET_NUM as targetNum, R.REPORT_REASON as reportReason, R.REPORT_STATUS as reportStatus, R.REPORT_DATE as reportDate, NVL( CASE WHEN R.TARGET_TYPE = 'POST' THEN SUBSTR(P.POST_TITLE, 1, 50) WHEN R.TARGET_TYPE = 'COMMENT' THEN SUBSTR(C.COMMENT_CONTENT, 1, 50) END, '내용 없음 (삭제됨)' ) as targetContentPreview FROM T_REPORT R LEFT JOIN T_USER U ON R.REPORTER_NUM = U.USER_NUM LEFT JOIN T_POST P ON R.TARGET_TYPE = 'POST' AND R.TARGET_NUM = P.POST_NUM LEFT JOIN T_COMMENT C ON R.TARGET_TYPE = 'COMMENT' AND R.TARGET_NUM = C.COMMENT_NUM
R.REPORT_STATUS = #{status}
ORDER BY R.REPORT_DATE DESC OFFSET #{offset} ROWS FETCH NEXT #{limit} ROWS ONLY

mapper.update:
UPDATE T_REPORT
SET REPORT_STATUS = #{status}
WHERE REPORT_NUM = #{reportNum}
